from Crypto.Util.number import getPrime, bytes_to_long
from math import gcd

e = 65537

flag = b"holic{fake_flag_for_testing}"

while True:
    p = getPrime(512)
    q = getPrime(512)
    if p != q and gcd(e, (p-1)*(q-1)) == 1:
        break

n = p * q
m = bytes_to_long(flag)
c = pow(m, e, n)

leak = (~p) // (1 << 240)

print(f"n = {n}")
print(f"e = {e}")
print(f"c = {c}")
print(f"leak = {leak}")

